func (workflowStepWhere[Q]) AliasedAs(alias string) workflowStepWhere[Q] {
	return buildWorkflowStepWhere[Q](buildWorkflowStepColumns(alias))
}

func buildWorkflowStepWhere[Q sqlite.Filterable](cols workflowStepColumns) workflowStepWhere[Q] {
	return workflowStepWhere[Q]{
		cols:        cols,
		RunID:       sqlite.Where[Q, string](cols.RunID.Expression),
		Seq:         sqlite.Where[Q, int64](cols.Seq.Expression),
		Kind:        sqlite.Where[Q, string](cols.Kind.Expression),
		Name:        sqlite.Where[Q, string](cols.Name.Expression),
		InputHash:   sqlite.Where[Q, string](cols.InputHash.Expression),
		Status:      sqlite.Where[Q, string](cols.Status.Expression),
		Input:       sqlite.WhereNull[Q, types.JSON[json.RawMessage]](cols.Input.Expression),
		Output:      sqlite.WhereNull[Q, []byte](cols.Output.Expression),
		Error:       sqlite.WhereNull[Q, string](cols.Error.Expression),
		StartedAt:   sqlite.Where[Q, time.Time](cols.StartedAt.Expression),
		CompletedAt: sqlite.WhereNull[Q, time.Time](cols.CompletedAt.Expression),
		R:           workflowStepWhereR[Q]{cols: cols},
	}
}

// workflowStepWhereR holds the relationship-based filters of
// workflowStepWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type workflowStepWhereR[Q sqlite.Filterable] struct {
	cols workflowStepColumns
}

// HasRunWorkflowRun filters parents that have a matching RunWorkflowRun using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to WorkflowRuns).
func (w workflowStepWhereR[Q]) HasRunWorkflowRun(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(WorkflowRuns.NameExpr()),
		sm.Where(WorkflowRuns.Columns.ID.EQ(w.cols.RunID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}
